import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2
    for _ in range(n):
        grid.append(data[idx])
        idx += 1

    painted = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '#':
                painted.append((r, c))

    if len(painted) <= 1:
        print(-1)
        return

    def get_neighbors(r, c):
        res = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '#':
                res.append((nr, nc))
        return res

    def is_connected(start_node):
        visited = set()
        queue = deque([start_node])
        visited.add(start_node)
        while queue:
            r, c = queue.popleft()
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == len(painted)

    if not is_connected(painted[0]):
        print(0)
        return

    for r, c in painted:
        grid[r] = grid[r][:c] + '.' + grid[r][c+1:]
        if not is_connected(painted[0]):
            print(1)
            return
        grid[r] = grid[r][:c] + '#' + grid[r][c+1:]

    print(2)

if __name__ == "__main__":
    solve()
